"use client";

import type { VariantProps } from "class-variance-authority";
import type * as React from "react";
import { cn } from "../utils/cn";
import { Slot } from "../utils/slot";
import { buttonVariants } from "./button-variants";

// ─── Spinner ──────────────────────────────────────────────────────────────────
// Uses @keyframes spinner from globals.css

function Spinner({ className }: { className?: string }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        "block rounded-full border-2 border-current border-t-transparent animate-[spinner_0.6s_linear_infinite]",
        className,
      )}
    />
  );
}

// ─── Icon size class mapping ──────────────────────────────────────────────────

function getIconSizeClass(size: string | null | undefined): string {
  switch (size) {
    case "tiny":
      return "[&>svg]:size-3"; // 12px
    case "sm":
      return "[&>svg]:size-3.5"; // 14px
    case "lg":
      return "[&>svg]:size-4.5"; // 18px
    default:
      return "[&>svg]:size-4"; // 16px
  }
}

function getSpinnerSizeClass(size: string | null | undefined): string {
  switch (size) {
    case "tiny":
      return "size-3"; // 12px
    case "sm":
      return "size-3.5"; // 14px
    case "lg":
      return "size-4.5"; // 18px
    default:
      return "size-4"; // 16px
  }
}

// ─── Shadow class mapping ─────────────────────────────────────────────────────

const SHADOW_CLASSES: Record<string, string> = {
  sm: "shadow-sm",
  md: "shadow-md",
  lg: "shadow-lg",
};

function resolveShadowClass(shadow: boolean | "sm" | "md" | "lg" | undefined): string | undefined {
  if (!shadow) return undefined;
  const level = shadow === true ? "md" : shadow;
  return SHADOW_CLASSES[level];
}

// ─── ButtonContent (shared between Button & ButtonLink) ───────────────────────

interface ButtonContentProps {
  loading: boolean;
  prefix?: React.ReactNode | undefined;
  suffix?: React.ReactNode | undefined;
  size?: string | null | undefined;
  children?: React.ReactNode | undefined;
}

function ButtonContent({ loading, prefix, suffix, size, children }: ButtonContentProps) {
  const iconSizeClass = getIconSizeClass(size);

  return (
    <>
      {loading && <Spinner className={getSpinnerSizeClass(size)} />}
      {prefix != null && (
        <span aria-hidden="true" className={cn("shrink-0", iconSizeClass)}>
          {prefix}
        </span>
      )}
      {children}
      {suffix != null && (
        <span aria-hidden="true" className={cn("shrink-0", iconSizeClass)}>
          {suffix}
        </span>
      )}
    </>
  );
}

// ─── Button ───────────────────────────────────────────────────────────────────

export interface ButtonProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "prefix">,
    VariantProps<typeof buttonVariants> {
  /** Render as a child element (Radix Slot — polymorphic) */
  asChild?: boolean;
  /** Show loading spinner and disable interaction */
  loading?: boolean;
  /** Icon or element rendered before children */
  prefix?: React.ReactNode;
  /** Icon or element rendered after children */
  suffix?: React.ReactNode;
  /** Elevation shadow level. `true` resolves to `"md"` */
  shadow?: boolean | "sm" | "md" | "lg";
}

const Button = ({
  className,
  variant,
  size,
  shape,
  asChild = false,
  loading = false,
  disabled,
  prefix,
  suffix,
  shadow,
  children,
  ref,
  ...props
}: ButtonProps & { ref?: React.Ref<HTMLButtonElement> | undefined }) => {
  const Comp = asChild ? Slot : "button";
  const isDisabled = Boolean(disabled || loading);
  const shadowClass = resolveShadowClass(shadow);

  return (
    <Comp
      ref={ref}
      className={cn(buttonVariants({ variant, size, shape }), shadowClass, className)}
      disabled={isDisabled}
      aria-busy={loading || undefined}
      {...props}
    >
      {asChild ? (
        children
      ) : (
        <ButtonContent loading={loading} prefix={prefix} suffix={suffix} size={size}>
          {children}
        </ButtonContent>
      )}
    </Comp>
  );
};
Button.displayName = "Button";

// ─── ButtonLink ───────────────────────────────────────────────────────────────

export interface ButtonLinkProps
  extends Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, "prefix">,
    VariantProps<typeof buttonVariants> {
  /** Icon or element rendered before children */
  prefix?: React.ReactNode;
  /** Icon or element rendered after children */
  suffix?: React.ReactNode;
  /** Elevation shadow level. `true` resolves to `"md"` */
  shadow?: boolean | "sm" | "md" | "lg";
  /** Show loading spinner */
  loading?: boolean;
}

const ButtonLink = ({
  className,
  variant,
  size,
  shape,
  prefix,
  suffix,
  shadow,
  loading = false,
  children,
  ref,
  ...props
}: ButtonLinkProps & { ref?: React.Ref<HTMLAnchorElement> | undefined }) => {
  const shadowClass = resolveShadowClass(shadow);

  const loadingProps = loading
    ? {
        "aria-busy": "true" as const,
        "aria-disabled": "true" as const,
        tabIndex: -1,
      }
    : {};

  return (
    <a
      ref={ref}
      className={cn(
        buttonVariants({ variant, size, shape }),
        shadowClass,
        loading && "pointer-events-none opacity-50",
        className,
      )}
      {...loadingProps}
      {...props}
    >
      <ButtonContent loading={loading} prefix={prefix} suffix={suffix} size={size}>
        {children}
      </ButtonContent>
    </a>
  );
};
ButtonLink.displayName = "ButtonLink";

export { Button, ButtonLink };

import { cva } from "class-variance-authority";

// Heights: tiny=24px sm=32px md=40px lg=48px (Geist-matching).
// Focus ring uses the shared neutral ring token, 2px ring, 2px offset.
export const buttonVariants = cva(
  [
    "inline-flex items-center justify-center gap-2 whitespace-nowrap",
    "rounded-[var(--radius-md)] text-sm font-medium",
    "transition-colors duration-micro ease-out",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
    "disabled:pointer-events-none disabled:opacity-50",
    "aria-busy:cursor-wait",
  ].join(" "),
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        ink: "bg-[var(--neutral-12)] text-[var(--neutral-1)] ring-1 ring-inset ring-[color:var(--neutral-1)]/5 hover:bg-[var(--neutral-11)] hover:-translate-y-px active:translate-y-0 transition-[transform,background-color] duration-micro",
        destructive: "bg-destructive text-destructive-foreground hover:bg-destructive/90",
        outline: "border border-input bg-background hover:bg-accent hover:text-accent-foreground",
        secondary: "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        link: "text-primary underline-offset-4 hover:underline",
        tertiary:
          "border border-transparent bg-transparent text-muted-foreground hover:bg-accent hover:text-accent-foreground hover:border-input",
        warning: "bg-warning text-warning-foreground hover:bg-warning/90",
      },
      size: {
        tiny: "h-6 rounded-[var(--radius-sm)] px-2 text-[11px]",
        sm: "h-8 rounded-[var(--radius-sm)] px-3 text-xs",
        default: "h-10 px-4 py-2",
        lg: "h-12 rounded-[var(--radius-lg)] px-5 text-base",
        icon: "h-10 w-10",
      },
      shape: {
        default: "",
        square: "",
        circle: "",
      },
    },
    compoundVariants: [
      { shape: "square", size: "tiny", className: "w-6 px-0" },
      { shape: "square", size: "sm", className: "w-8 px-0" },
      { shape: "square", size: "default", className: "w-10 px-0" },
      { shape: "square", size: "lg", className: "w-12 px-0" },
      { shape: "circle", size: "tiny", className: "w-6 px-0 rounded-full" },
      { shape: "circle", size: "sm", className: "w-8 px-0 rounded-full" },
      { shape: "circle", size: "default", className: "w-10 px-0 rounded-full" },
      { shape: "circle", size: "lg", className: "w-12 px-0 rounded-full" },
    ],
    defaultVariants: {
      variant: "default",
      size: "default",
      shape: "default",
    },
  },
);

"use client";

import * as React from "react";

export interface SlotProps extends React.HTMLAttributes<HTMLElement> {
  children?: React.ReactNode;
}

/**
 * Custom Slot implementation to remove @radix-ui/react-slot dependency.
 * Merges props from the Slottable parent onto the immediate child element.
 */
export const Slot = React.forwardRef<HTMLElement, SlotProps>(
  ({ children, className, style, ...props }, ref) => {
    // Resolve the single child without using React.Children.only — which throws
    // when children is a single-element array, fragment, or a string. Prerender
    // pipelines sometimes wrap JSX children in arrays of length 1, which passes
    // React.Children.count(=== 1) but trips React.Children.only.
    const childArray = React.Children.toArray(children);
    const child = childArray.length === 1 ? childArray[0] : null;

    if (child == null || !React.isValidElement(child)) {
      // 0 / 2+ / non-element child — graceful span wrapper instead of throwing.
      return (
        <span ref={ref} className={className} style={style} {...props}>
          {children}
        </span>
      );
    }

    const childProps = child.props as React.HTMLAttributes<HTMLElement>;
    const mergedRef = (node: HTMLElement | null) => {
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;

      // React 19 removed `element.ref` — the ref is now a regular prop, so read
      // it from the child's props (reading `child.ref` triggers the removal warning).
      const childRef = (
        childProps as React.HTMLAttributes<HTMLElement> & { ref?: React.Ref<HTMLElement> }
      ).ref;
      if (typeof childRef === "function") childRef(node);
      else if (childRef && "current" in childRef) {
        (childRef as React.MutableRefObject<HTMLElement | null>).current = node;
      }
    };
    // Order matters: slot's props seed → child's existing props override →
    // explicit className/style/ref take precedence over both (so the slot's
    // className/style merge with the child's, not the child's alone).
    const mergedClass = [className, childProps.className].filter(Boolean).join(" ");
    const merged: Record<string, unknown> = {
      ...childProps,
      ...props,
      ref: mergedRef,
      className: mergedClass,
      style: { ...childProps.style, ...style },
    };
    return React.cloneElement(
      child,
      merged as React.HTMLAttributes<HTMLElement> & React.RefAttributes<HTMLElement>,
    );
  },
);

Slot.displayName = "Slot";

/**
 * Slottable acts as a marker. In this simple implementation,
 * we just resolve it as a fragment wrapper. For deeper `asChild` composition,
 * complex logic is usually required, but most primitives just need `Slot`.
 */
export const Slottable: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  return <>{children}</>;
};
